function sha1(bytes) {
  const ml = bytes.length * 8, avecUn = bytes.length + 1, len = avecUn + ((56 - (avecUn % 64)) + 64) % 64 + 8;
  const m = new Uint8Array(len); m.set(bytes); m[bytes.length] = 0x80;
  const dv = new DataView(m.buffer); dv.setUint32(len - 4, ml >>> 0); dv.setUint32(len - 8, Math.floor(ml / 2 ** 32));
  let h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476, h4 = 0xC3D2E1F0; const w = new Uint32Array(80);
  for (let i = 0; i < len; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = dv.getUint32(i + t * 4);
    for (let t = 16; t < 80; t++) { const x = w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16]; w[t] = (x << 1) | (x >>> 31); }
    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let t = 0; t < 80; t++) {
      const [f, k] = t < 20 ? [(b & c) | (~b & d), 0x5A827999] : t < 40 ? [b ^ c ^ d, 0x6ED9EBA1] : t < 60 ? [(b & c) | (b & d) | (c & d), 0x8F1BBCDC] : [b ^ c ^ d, 0xCA62C1D6];
      const tmp = (((a << 5) | (a >>> 27)) + f + e + k + w[t]) >>> 0; e = d; d = c; c = ((b << 30) | (b >>> 2)) >>> 0; b = a; a = tmp;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }
  return [h0, h1, h2, h3, h4].map(x => x.toString(16).padStart(8, '0')).join('');
}
// SHA d'un fichier tel que git (et GitHub) le calcule : sha1("blob <taille>\0<contenu>")
const shaGit = txt => { const c = Buffer.from(txt, 'utf8'); return sha1(new Uint8Array(Buffer.concat([Buffer.from('blob ' + c.length + '\0'), c]))); };
// 1. Nettoyage : ni données épinglées, ni état interne, ni propriétaire, et les secrets écrits en clair sont masqués.
// 2. Comparaison avec la dernière sauvegarde (SHA git) : seuls les fichiers nouveaux ou modifiés partent dans le commit.
const reg = $('Réglages').first().json;
const MOTIFS = [/sk-[A-Za-z0-9_-]{20,}/g, /gh[pousr]_[A-Za-z0-9]{30,}/g, /github_pat_[A-Za-z0-9_]{30,}/g, /xox[abpr]-[A-Za-z0-9-]{10,}/g,
  /AKIA[0-9A-Z]{16}/g, /AIza[0-9A-Za-z_-]{30,}/g, /Bearer\s+[A-Za-z0-9._~+\/-]{20,}/gi, /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g];
const CLES_SENSIBLES = /^(password|passwd|mot_?de_?passe|api_?key|apikey|token|secret|client_?secret)$/i;
const MASQUE = '«secret masqué par la sauvegarde»';
const alertes = [];
function masquer(v, wfNom, noeud, cle) {
  if (typeof v === 'string') {
    let r = v;
    if (CLES_SENSIBLES.test(cle ?? '') && v && !v.startsWith('=')) r = MASQUE;
    for (const m of MOTIFS) r = r.replace(m, MASQUE);
    if (r !== v) alertes.push({ workflow: wfNom, noeud });
    return r;
  }
  if (Array.isArray(v)) return v.map(x => masquer(x, wfNom, noeud, cle));
  if (v && typeof v === 'object') {
    // Paire « name / value » (en-têtes, paramètres) : le nom décide si la valeur est sensible
    const nomPaire = typeof v.name === 'string' ? v.name : null;
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, masquer(x, wfNom, noeud, k === 'value' && nomPaire ? nomPaire : k)]));
  }
  return v;
}
const slug = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const wfs = $('Lister les workflows').all().flatMap(p => p.json.data ?? []);
if (!wfs.length) throw new Error('Aucun workflow reçu de l\'API n8n : vérifiez l\'adresse et la clé.');
const existants = new Map(($('Fichiers déjà sauvegardés').first().json.tree ?? []).filter(e => e.type === 'blob').map(e => [e.path, e.sha]));

const fichiers = [], lignes = [];
for (const w of wfs) {
  const propre = {
    id: w.id, name: w.name, active: !!w.active, tags: (w.tags ?? []).map(t => t.name ?? t),
    settings: w.settings ?? {}, connections: w.connections ?? {},
    nodes: (w.nodes ?? []).map(n => ({ ...n, parameters: masquer(n.parameters ?? {}, w.name, n.name, '') })),
  };
  const chemin = reg.dossier + '/' + slug(w.name) + '--' + w.id + '.json';
  const contenu = JSON.stringify(propre, null, 2) + '\n';
  const statut = !existants.has(chemin) ? 'nouveau' : existants.get(chemin) === shaGit(contenu) ? 'inchangé' : 'modifié';
  if (statut !== 'inchangé') fichiers.push({ path: chemin, mode: '100644', type: 'blob', content: contenu });
  lignes.push({ nom: w.name, id: w.id, actif: !!w.active, noeuds: propre.nodes.length, chemin, statut,
    epingles: Object.keys(w.pinData ?? {}).length > 0 });
}
const actuels = new Set(lignes.map(l => l.chemin));
const archives = [...existants.keys()].filter(p => p.startsWith(reg.dossier + '/') && !actuels.has(p));
const secrets = [...new Map(alertes.map(a => [a.workflow + '|' + a.noeud, a])).values()];

// Index lisible à la racine du dépôt (sans date, pour ne changer que si le contenu change)
const index = ['# Sauvegarde des workflows n8n', '', 'Mise à jour automatiquement. Un fichier par workflow, l\'historique est dans les commits.', '',
  '| Workflow | Actif | Nœuds | Fichier |', '|---|---|---|---|',
  ...lignes.slice().sort((a, b) => a.nom.localeCompare(b.nom)).map(l => `| ${l.nom} | ${l.actif ? 'oui' : 'non'} | ${l.noeuds} | [${l.chemin.split('/').pop()}](${l.chemin}) |`), '',
  ...(secrets.length ? ['## Secrets masqués', '', 'Ces nœuds contenaient une clé écrite en clair. Elle a été masquée dans la sauvegarde ; déplacez-la dans un identifiant n8n.', '',
    ...secrets.map(s => `- ${s.workflow} › ${s.noeud}`), ''] : []),
  ...(archives.length ? ['## Archivés', '', 'Workflows supprimés de n8n : leur dernière sauvegarde est conservée.', '', ...archives.map(a => '- ' + a), ''] : []),
].join('\n');
if (existants.get('README.md') !== shaGit(index)) fichiers.push({ path: 'README.md', mode: '100644', type: 'blob', content: index });

const n = s => lignes.filter(l => l.statut === s).length;
const date = $now.setZone('Europe/Paris').setLocale('fr').toFormat("d LLLL yyyy 'à' HH'h'mm");
const note = $('Sauvegarder maintenant').isExecuted ? ($('Sauvegarder maintenant').first().json.note || '') : '';
return [{ json: {
  a_commiter: fichiers.length > 0, fichiers,
  message: `Sauvegarde du ${date} : ${n('modifié')} modifié(s), ${n('nouveau')} nouveau(x)${note ? ' · ' + note : ''}`,
  base_commit: $('Branche GitHub').first().json.object.sha, base_tree: $('Dernier commit').first().json.tree.sha,
  lignes, secrets, archives, total: lignes.length, modifies: n('modifié'), nouveaux: n('nouveau'), inchanges: n('inchangé'),
  epingles: lignes.filter(l => l.epingles).length,
} }];

// Rapport : ce qui a été sauvegardé, et ce qui mérite votre attention.
const p = $('Préparer la sauvegarde').first().json;
const commit = $('Créer le commit').isExecuted ? $('Créer le commit').first().json : null;
return [{ json: { ...p, commit_sha: commit?.sha ?? null, commit_court: commit ? commit.sha.slice(0, 7) : null,
  commit_url: commit?.html_url ?? null, depot: $('Réglages').first().json.depot } }];

// Retrouve le fichier du workflow demandé (par identifiant ou par nom) dans la version choisie.
const demande = String($('Restaurer un workflow').first().json.workflow ?? '').trim().toLowerCase();
const slug = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const dossier = $('Réglages').first().json.dossier + '/';
const fichiers = ($json.tree ?? []).filter(e => e.type === 'blob' && e.path.startsWith(dossier) && e.path.endsWith('.json'));
const trouve = fichiers.find(f => f.path.toLowerCase().endsWith('--' + demande + '.json')) ?? fichiers.find(f => f.path.split('/').pop().startsWith(slug(demande) + '--'));
if (!trouve) throw new Error('Aucune sauvegarde ne correspond à « ' + demande + ' » dans cette version.');
return [{ json: { chemin: trouve.path } }];

// Reconstruit le workflow pour l'API n8n : il est recréé en copie, inactif, sans toucher à l'original.
const w = JSON.parse(Buffer.from($json.content, 'base64').toString('utf8'));
const version = $('Restaurer un workflow').first().json.version || $('Réglages').first().json.branche;
const AUTORISES = ['saveExecutionProgress', 'saveManualExecutions', 'saveDataErrorExecution', 'saveDataSuccessExecution', 'executionTimeout', 'errorWorkflow', 'timezone', 'executionOrder', 'callerPolicy'];
const settings = Object.fromEntries(Object.entries(w.settings ?? {}).filter(([k]) => AUTORISES.includes(k)));
const masques = (JSON.stringify(w.nodes).match(/secret masqué par la sauvegarde/g) ?? []).length;
const date = $now.setZone('Europe/Paris').toFormat('dd/LL/yyyy');
return [{ json: { corps: { name: w.name + ' (restauré le ' + date + ')', nodes: w.nodes, connections: w.connections, settings },
  origine: w.name, version, masques } }];
